int secure_erase(const char *path)
{
    int fd;
    struct stat st;
    off_t remaining;
    static const unsigned char zeros[65536];

    if (path == NULL) {
        errno = EINVAL;
        return -1;
    }

    fd = open(path, O_WRONLY | O_NOFOLLOW);
    if (fd < 0) {
        return -1;
    }

    if (fstat(fd, &st) < 0) {
        close(fd);
        return -1;
    }

    if (!S_ISREG(st.st_mode)) {
        close(fd);
        errno = EINVAL;
        return -1;
    }

    if (lseek(fd, 0, SEEK_SET) < 0) {
        close(fd);
        return -1;
    }

    remaining = st.st_size;
    while (remaining > 0) {
        size_t chunk = (remaining < (off_t)sizeof(zeros))
                       ? (size_t)remaining
                       : sizeof(zeros);
        ssize_t written = write(fd, zeros, chunk);

        if (written < 0) {
            if (errno == EINTR) {
                continue;
            }
            close(fd);
            return -1;
        }
        if (written == 0) {
            close(fd);
            errno = EIO;
            return -1;
        }
        remaining -= (off_t)written;
    }

    if (fsync(fd) < 0) {
        close(fd);
        return -1;
    }

    if (close(fd) < 0) {
        return -1;
    }

    if (remove(path) < 0) {
        return -1;
    }

    return 0;
}

